/* From Uiverse.io by Ratinax - Tags: radio, buttons, traffic light, traffic-light */
.__UIV_SCOPE__ .container {
  scale: 0.7;
}

.__UIV_SCOPE__ .fire {
  width: 2em;
  height: 6.5em;
  background-color: black;
  border-radius: 1em;
  display: flex;
  justify-content: center;
  align-items: center;
  flex-direction: column;
}

.__UIV_SCOPE__ .label {
  width: 1.5em;
  height: 1.5em;
  border-radius: 50%;
  margin-top: .25em;
  margin-bottom: .25em;
  border-top: .2em solid black;
  cursor: pointer;
}

.__UIV_SCOPE__ .input {
  display: none;
}

.__UIV_SCOPE__ .label.red {
  background-color: #990000;
  box-shadow: 0 0 2em #990000;
}

.__UIV_SCOPE__ .label.orange {
  background-color: #999900;
  box-shadow: 0 0 2em #999900;
}

.__UIV_SCOPE__ .label.green {
  background-color: #009900;
  box-shadow: 0 0 2em #009900;
}

.__UIV_SCOPE__ .label.red:hover {
  background-color: red;
}

.__UIV_SCOPE__ .label.orange:hover {
  background-color: orange;
}

.__UIV_SCOPE__ .label.green:hover {
  background-color: lime;
}

.__UIV_SCOPE__ .label.red:has(input:checked) {
  background-color: red;
  box-shadow: 0 0 2em red;
}

.__UIV_SCOPE__ .label.orange:has(input:checked) {
  background-color: orange;
  box-shadow: 0 0 2em orange;
}

.__UIV_SCOPE__ .label.green:has(input:checked) {
  background-color: lime;
  box-shadow: 0 0 2em lime;
}
